/**
 * Hand-written complement to the generated CLI reference: examples, what the output looks like and the failures a developer
 * will actually meet. Usage, summaries and flags always come from the command registry, so they cannot drift.
 */
export interface CliNote {
  /** replaces the command's own summary on its documentation page and in the CLI index (the command's --help is unchanged) */
  summary?: string;
  examples: string[]; output?: string; failures?: string[]; see?: string[]; effects?: string[]; checks?: string[]; flags?: Record<string, string> }

