  "make:hook": { summary: "Generate a lifecycle hook (onReady / onShutdown) in the module's `hooks/` folder (`src/modules/<module>/hooks/`, `--module` is required in the official structure) and list it in that module's providers (a hook nobody lists never runs); a 0.1 project writes `src/hooks/`", examples: ["pso make:hook audit --module users --service gateway --dry-run","pso make:hook audit --module users --service gateway"], effects: ["Writes `src/modules/users/hooks/audit.hook.ts`: an injectable class implementing `onReady` (after start-up succeeded, before the application reports ready; throwing stops start-up) and `onShutdown` (after running requests finished, before the framework releases its resources).","`--module users` adds the class to `providers` of that module's `MODULE.pso.ts`. A hook runs only when a module lists it: a file in a `hooks/` folder is never run on its own."], checks: ["Start the orchestrator: the log has `hook ready` and `lifecycle hooks ran` before `orchestrator listening`.","`pso validate` checks the module declaration."], output: "updated  src/modules/users/MODULE.pso.ts\ncreated  src/modules/users/hooks/audit.hook.ts", failures: ["`Module \"users\" does not exist`: create it with `pso make:module users`.","`In the modular structure a hook belongs to a module`: pass `--module <module>`.","`A hook is generated in the orchestrator`: Spring services use Spring's own lifecycle callbacks."], see: ["concepts/runtime-lifecycle","orchestrator/services-and-providers"] },
  "make:listener": { examples: ["pso make:listener order-placed --service orders --dry-run","pso make:listener order-placed --service orders"], effects: ["Writes `application/event/OrderPlacedListener.java` (`events/` in a 0.1 service): a component with an `@EventListener` method for the LOCAL application event of the same name (typed with `OrderPlacedEvent` when `pso make:event order-placed` created it).","It is not a Dispatch consumer: events of other services are handled by a `@PsoEventHandler` method, generated with `pso make:dispatch-handler`."], failures: ["Without the event class the method takes `Object` and a comment names the command that creates the event."], see: ["microservices/hexagonal-architecture","dispatch/events-and-consumers"] },
