  "make:port": { examples: ["pso make:port payment --service orders --dry-run", "pso make:port payment --service orders"], failures: ["The generated port is an application contract; provide an adapter implementation before using it."], see: ["microservices/hexagonal-architecture"] },
  "make:provider": { summary: "Generate an injectable provider class in the module's `providers/` folder (`src/modules/<module>/providers/`, `--module` is required in the official structure) and list it in that module's providers (explicit registration: a provider nobody lists is never constructed); a 0.1 project writes `src/providers/`", examples: ["pso make:provider clock --module users --service gateway --dry-run","pso make:provider clock --module users --service gateway"], effects: ["Writes `src/modules/users/providers/clock.provider.ts`: an `@Injectable()` class the framework constructs once per application and injects by constructor type.","`--module users` adds the class to `providers` of that module's `MODULE.pso.ts`. Registration is explicit: a provider that no module lists is never constructed."], checks: ["Inject it in a controller or service of the module by constructor type, then run `pso validate`."], output: "updated  src/modules/users/MODULE.pso.ts\ncreated  src/modules/users/providers/clock.provider.ts", failures: ["`Module \"users\" does not exist`: create it with `pso make:module users`.","`In the modular structure a provider belongs to a module`: pass `--module <module>`.","`PSO_MODULE_006` from `pso validate`: a class injects the provider but its module does not list it."], see: ["orchestrator/services-and-providers","orchestrator/dependency-injection"] },
  "make:dispatch-event": { examples: ["pso make:dispatch-event orders.placed --service orders --fields \"orderId:string,customerId:string,total:number\" --key orderId","pso make:dispatch-event orders.placed --service billing --consume-only --fields \"orderId:string,customerId:string,total:number\"","pso make:dispatch-event orders.placed --service gateway --consume-only --fields \"orderId:string\""], effects: ["Declares a DISTRIBUTED event: one that travels through the configured broker (Redis Streams, RabbitMQ, Kafka) to every service that declares it.","Spring Boot: adds the event with its schema to `src/main/resources/dispatch/<service>.events.json` and writes the payload record `application/event/OrdersPlacedEvent.java` (`events/` in a 0.1 service).","Orchestrator: adds the event to `src/dispatch/<module>/EVENTS.pso.ts` (created when missing) and writes its schema under `schemas/`.","`--consume-only` declares an event another service publishes (`publish: false`)."], checks: ["`pso dispatch:validate` checks the declaration and `pso dispatch:events` lists it; `pso dispatch:lock` records the contract.","Declarations are inert until a provider is installed (`pso dispatch:install`) and Dispatch is enabled."], flags: {"--fields":"The payload: `name:type` with type string, integer, number or boolean; `name?` is optional.","--key":"A required field that orders the events of one entity.","--channel":"The broker channel; default `<first segment of the name>.events`.","--version":"The contract version; a published version is never edited.","--consume-only":"This project receives the event and never publishes it.","--module":"Orchestrator only: the folder under `src/dispatch/`."}, output: "updated    src/main/resources/dispatch/orders.events.json\ncreated    src/main/java/com/pso/orders/application/event/OrdersPlacedEvent.java", failures: ["`orders.placed version 1 is already declared`: declare the next `--version` for a change.","`@pso/dispatch is not a dependency of this orchestrator`: run `pso dispatch:install <provider>` first.","It is not `pso make:event`, which creates a local Spring application event."], see: ["dispatch/events-and-consumers","dispatch/contracts"] },
  "make:dispatch-handler": { examples: ["pso make:dispatch-handler orders.placed --service billing","pso make:dispatch-handler orders.placed --service gateway --group gateway-notifications"], effects: ["Generates a consumer of an event the project already declares.","Spring Boot: `application/event/OrdersPlacedHandler.java` (`events/` in a 0.1 service), a component with a `@PsoEventHandler(\"orders.placed\")` method.","Orchestrator: a `@DispatchConsumer` class in `src/dispatch/<module>/`, listed in `consumers` of `EVENTS.pso.ts` (a consumer that is not listed never runs)."], checks: ["`pso dispatch:consumers` lists the consumer; `pso dispatch:validate` checks it against the declaration."], failures: ["`\"orders.placed\" is not declared in this service`: declare it first with `pso make:dispatch-event orders.placed --consume-only`.","Delivery is at least once: the handler must be idempotent."], see: ["dispatch/events-and-consumers","dispatch/reliability"] },
