  "types": { examples: ["pso types","pso types --check","pso types --dry-run"], effects: ["Writes `src/pso-types.d.ts` in the orchestrator: the services registered in `pso.workspace.json` and the guards of the project as TypeScript types.","From then on the compiler refuses a service or guard name that does not exist in `ROUTES.pso.ts`, `Upstream.forward` and `UpstreamClient`. Without the file every string is accepted, as before."], checks: ["`npm run typecheck` in the orchestrator.","`pso types --check` exits 1 when the file is missing or out of date (for a pipeline)."], output: "created    gateway/src/pso-types.d.ts\nservices: catalog, customers, orders\nguards:   jwt", failures: ["Run it again after `pso create service`, `pso services:register` or `pso make:guard`: the file is generated, never edited by hand.","The run-time checks do not depend on it: `pso validate` and start-up refuse an unknown service or guard either way."], see: ["orchestrator/routes","orchestrator/upstream-clients"] },
  "idp:dev": { examples: ["pso idp:dev init","pso tls:init --dev --hosts idp","docker compose -f docker-compose.yml -f docker-compose.idp.yml up -d --wait","pso idp:dev token --scopes orders:read,orders:write","pso idp:dev token --sub alice --roles admin --ttl 300 --json","pso idp:dev serve --port 9443"], effects: ["`init` generates a signing key pair on this machine (`idp/keys/`, git-ignored), its public key set (`idp/jwks.json`), a dependency-free JWKS server (`idp/dev-idp.cjs`) and the Compose overlay `docker-compose.idp.yml`, and prints the `PSO_JWT_*` values for `.env`.","`token` signs a development JWT (ES256) for a synthetic identity and prints only the token, so it can be used as `$(pso idp:dev token ...)`.","`serve` publishes the public keys on loopback over plain HTTP for `pso dev`.","The JWKS server holds public keys only: the private key never enters a container or an image."], checks: ["`curl -H \"Authorization: Bearer $(pso idp:dev token --scopes orders:read)\" http://127.0.0.1:3000/orders` through the orchestrator.","A request without the token answers 401; with a token missing the scope, 403."], flags: {"--issuer":"The `iss` of the tokens and the base URL of the JWKS endpoint (default `https://idp:8443`).","--audience":"The `aud` the services require (default `pso-api`).","--host":"The container name of the identity provider in the overlay (default `idp`).","--scopes":"Scopes of the token, comma separated.","--roles":"Roles of the token, comma separated.","--ttl":"Lifetime of the token in seconds (default 900).","--sub":"The subject of the token (default `dev-user`)."}, failures: ["`does not run with PSO_ENV=production`: it is a development tool; production uses a real identity provider.","`No development identity provider`: run `pso idp:dev init` first.","`The signing key ... is missing`: the key exists only on the machine where `init` ran.","`pso security:check --env production` reports SEC013 when a production configuration names this issuer."], see: ["security/authentication","devops/docker","tutorials/authentication"] },
  "connection:add": { examples: ["pso connection:add prod --host 203.0.113.10 --user deploy --auth key --key ~/.ssh/id_ed25519", "pso connection:add prod --host 203.0.113.10 --user deploy --accept-host-key SHA256:AbCd...", "pso connection:add prod --host 10.0.0.5 --user deploy --jump ops@bastion.example:22 --accept-host-key SHA256:AbCd..."], effects: ["Asks the server for its SSH host keys and pins the one whose fingerprint you approve (known_hosts owned by PSO, `StrictHostKeyChecking=yes`).", "Stores a key passphrase or password only in the protected credential store; a private key file is referenced by path, never copied."], failures: ["Exit code 3 in a non-interactive shell without `--accept-host-key`: the fingerprint must be approved by a person.", "`No protected credential store is available`: PSO never falls back to plain text; configure one (see cloud/credentials-and-security).", "Passwords and passphrases are never arguments: use `--password-stdin` / `--passphrase-stdin` or the hidden prompt."], flags: { "--accept-host-key": "The SHA256 fingerprint you verified out of band.", "--password-stdin": "Read the SSH password from standard input.", "--passphrase-stdin": "Read the key passphrase from standard input." }, see: ["cloud/connect-a-server"] },
